/**
 * Generated by `createservice miniapp.ImportB2BAppService`
 */

const { faker } = require('@faker-js/faker')

const {
    makeClient,
    expectToThrowAccessDeniedErrorToResult,
    expectToThrowAuthenticationErrorToResult,
    expectToThrowGQLErrorToResult,
} = require('@open-condo/keystone/test.utils')

const { SMART_HOME_CATEGORY, BUSINESS_DEVELOPMENT_CATEGORY } = require('@condo/domains/miniapp/constants')
const { getDevicePermissions, getDevicePermissionFieldName } = require('@condo/domains/miniapp/schema/fields/devicePermissions')
const { REMOTE_SYSTEM } = require('@dev-portal-api/domains/common/constants/common')
const { PUBLISH_REQUEST_APPROVED_STATUS, AVAILABLE_ENVIRONMENTS, DEV_ENVIRONMENT } = require('@dev-portal-api/domains/miniapp/constants/publishing')
const {
    B2BApp,
    CondoB2BApp,
    createTestB2CApp,
    createOIDCClientByTestClient,
    createTestB2BApp,
    createCondoB2BApp,
    createTestB2BAppPublishRequest,
    importB2BAppByTestClient,
    publishB2BAppByTestClient,
} = require('@dev-portal-api/domains/miniapp/utils/testSchema')
const { makeLoggedInAdminClient, makeLoggedInSupportClient, makeRegisteredAndLoggedInUser, makeLoggedInCondoAdminClient } = require('@dev-portal-api/domains/user/utils/testSchema')

const { getEnvironmentalFieldName } = require('./fields/environmental')

describe('ImportB2BAppService', () => {
    let admin
    let support
    let condoAdmin
    let user
    let anonymous
    let app
    let condoDevApp
    let condoProdApp
    beforeAll(async () => {
        admin = await makeLoggedInAdminClient()
        condoAdmin = await makeLoggedInCondoAdminClient()
        support = await makeLoggedInSupportClient()
        user = await makeRegisteredAndLoggedInUser()
        anonymous = await makeClient()
    })
    describe('Access tests', () => {
        beforeEach(async () => {
            [app] = await createTestB2BApp(user);
            [condoDevApp] = await createCondoB2BApp(condoAdmin);
            [condoProdApp] = await createCondoB2BApp(condoAdmin)
        })
        test('Admin can import any app', async () => {
            const [result] = await importB2BAppByTestClient(admin, app, condoDevApp, condoProdApp)
            expect(result).toHaveProperty('success', true)
        })
        test('Support can import any app', async () => {
            const [result] = await importB2BAppByTestClient(support, app, condoDevApp, condoProdApp)
            expect(result).toHaveProperty('success', true)
        })
        test('App owner cannot import app', async () => {
            await expectToThrowAccessDeniedErrorToResult(async () => {
                await importB2BAppByTestClient(user, app, condoDevApp, condoProdApp)
            })
        })
        test('Anonymous cannot import app', async () => {
            await expectToThrowAuthenticationErrorToResult(async () => {
                await importB2BAppByTestClient(anonymous, app, condoDevApp, condoProdApp)
            })
        })
    })
    describe('Logic tests', () => {
        describe('App info', () => {
            let devPermissions
            let prodPermissions
            beforeEach(async () => {
                [app] = await createTestB2BApp(user)
                devPermissions = {}
                prodPermissions = {}

                for (const permission of getDevicePermissions({ listKey: 'B2BApp' })) {
                    const fieldName = getDevicePermissionFieldName(permission)
                    devPermissions[fieldName] = faker.datatype.boolean()
                    prodPermissions[fieldName] = faker.datatype.boolean()
                }

                [condoDevApp] = await createCondoB2BApp(condoAdmin, {
                    developerUrl: faker.internet.url(),
                    shortDescription: faker.lorem.sentence(),
                    detailedDescription: faker.lorem.paragraph(),
                    category: SMART_HOME_CATEGORY,
                    contextDefaultStatus: 'InProgress',
                    appUrl: `https://${faker.internet.domainName()}`,
                    ...devPermissions,
                });
                [condoProdApp] = await createCondoB2BApp(condoAdmin, {
                    developerUrl: faker.internet.url(),
                    shortDescription: faker.lorem.sentence(),
                    detailedDescription: faker.lorem.paragraph(),
                    category: BUSINESS_DEVELOPMENT_CATEGORY,
                    contextDefaultStatus: 'Finished',
                    appUrl: `https://${faker.internet.domainName()}`,
                    ...prodPermissions,
                })
            })
            test('App must be updated with info from condo dev app if prod app is not specified', async () => {
                const [result] = await importB2BAppByTestClient(support, app, condoDevApp, null)
                expect(result).toHaveProperty('success', true)

                const updatedApp = await B2BApp.getOne(support, { id: app.id })
                expect(updatedApp).toHaveProperty('name', condoDevApp.name)
                expect(updatedApp).toHaveProperty('developer', condoDevApp.developer)
                expect(updatedApp).toHaveProperty('developerUrl', condoDevApp.developerUrl)
                expect(updatedApp).toHaveProperty('shortDescription', condoDevApp.shortDescription)
                expect(updatedApp).toHaveProperty('detailedDescription', condoDevApp.detailedDescription)
                expect(updatedApp).toHaveProperty('category', condoDevApp.category)
                expect(updatedApp).toHaveProperty('contextDefaultStatus', condoDevApp.contextDefaultStatus)
                expect(updatedApp).toHaveProperty(['logo', 'originalFilename'], condoDevApp.logo.filename)
                expect(updatedApp).toHaveProperty('developmentExportId', condoDevApp.id)
            })
            test('App must be updated with info from condo prod app if prod app is specified', async () => {
                const [result] = await importB2BAppByTestClient(support, app, condoDevApp, condoProdApp)
                expect(result).toHaveProperty('success', true)

                const updatedApp = await B2BApp.getOne(support, { id: app.id })
                expect(updatedApp).toHaveProperty('name', condoProdApp.name)
                expect(updatedApp).toHaveProperty('developer', condoProdApp.developer)
                expect(updatedApp).toHaveProperty('developerUrl', condoProdApp.developerUrl)
                expect(updatedApp).toHaveProperty('shortDescription', condoProdApp.shortDescription)
                expect(updatedApp).toHaveProperty('detailedDescription', condoProdApp.detailedDescription)
                expect(updatedApp).toHaveProperty('category', condoProdApp.category)
                expect(updatedApp).toHaveProperty('contextDefaultStatus', condoProdApp.contextDefaultStatus)
                expect(updatedApp).toHaveProperty(['logo', 'originalFilename'], condoProdApp.logo.filename)
                expect(updatedApp).toHaveProperty('productionExportId', condoProdApp.id)
            })
            test('Condo apps must be updated to include importId and importRemoteSystem', async () => {
                const [result] = await importB2BAppByTestClient(support, app, condoDevApp, condoProdApp)
                expect(result).toHaveProperty('success', true)

                const updatedDevApp = await CondoB2BApp.getOne(condoAdmin, { id: condoDevApp.id })
                expect(updatedDevApp).toHaveProperty('importId', app.id)
                expect(updatedDevApp).toHaveProperty('importRemoteSystem', REMOTE_SYSTEM)

                const updatedProdApp = await CondoB2BApp.getOne(condoAdmin, { id: condoProdApp.id })
                expect(updatedProdApp).toHaveProperty('importId', app.id)
                expect(updatedProdApp).toHaveProperty('importRemoteSystem', REMOTE_SYSTEM)
            })
            test('Environmental fields must be imported as well', async () => {
                const [dummyApp] = await createTestB2CApp(user)
                const [secondDummyApp] = await createTestB2CApp(user)
                const [{ id: oidcClientId }] = await createOIDCClientByTestClient(user, dummyApp)
                const [{ id: secondOidcClientId }] = await createOIDCClientByTestClient(user, secondDummyApp)
                await CondoB2BApp.update(condoAdmin, condoDevApp.id, {
                    dv: 1,
                    sender: { dv: 1, fingerprint: 'test-utilities' },
                    oidcClient: { connect: { id: oidcClientId } },
                })
                await CondoB2BApp.update(condoAdmin, condoProdApp.id, {
                    dv: 1,
                    sender: { dv: 1, fingerprint: 'test-utilities' },
                    oidcClient: { connect: { id: secondOidcClientId } },
                })

                const [result] = await importB2BAppByTestClient(support, app, condoDevApp, condoProdApp)
                expect(result).toHaveProperty('success', true)

                const updatedApp = await B2BApp.getOne(support, { id: app.id })
                const expectedPayload = {}
                for (const environment of AVAILABLE_ENVIRONMENTS) {
                    const app = environment === DEV_ENVIRONMENT ? condoDevApp : condoProdApp
                    const clientId = environment === DEV_ENVIRONMENT ? oidcClientId : secondOidcClientId
                    expectedPayload[getEnvironmentalFieldName(environment, 'appUrl')] = app.appUrl
                    expectedPayload[getEnvironmentalFieldName(environment, 'oidcClientId')] = clientId

                    const permissionsObj = environment === DEV_ENVIRONMENT ? devPermissions : prodPermissions
                    for (const [field, value] of Object.entries(permissionsObj)) {
                        const envFieldName = getEnvironmentalFieldName(environment, field.substring(2))
                        expectedPayload[envFieldName] = value
                    }
                }

                expect(updatedApp).toEqual(expect.objectContaining(expectedPayload))
            })
        })
        describe('Conflict policy', () => {
            describe.each(AVAILABLE_ENVIRONMENTS)('%p environment', (environment) => {
                let fromApp
                beforeEach(async () => {
                    // Create app - it auto-publishes and gets linked to a condo app
                    [app] = await createTestB2BApp(user)
                    if (environment !== DEV_ENVIRONMENT) {
                        await createTestB2BAppPublishRequest(support, app, {
                            isAppTested: true,
                            isContractSigned: true,
                            isInfoApproved: true,
                            status: PUBLISH_REQUEST_APPROVED_STATUS,
                        })
                    }
                    await publishB2BAppByTestClient(support, app, undefined, environment);
                    // Create a different condo app that we'll try to import - this creates a conflict
                    [fromApp] = await createCondoB2BApp(condoAdmin)
                })
                test('Must throw error on conflict if conflictPolicy is set to "panic"', async () => {
                    const devApp = environment === DEV_ENVIRONMENT ? fromApp : null
                    const prodApp = devApp ? null : fromApp
                    await expectToThrowGQLErrorToResult(async () => {
                        await importB2BAppByTestClient(support, app, devApp, prodApp, { options: { conflictPolicy: 'panic' } })
                    }, {
                        code: 'INTERNAL_ERROR',
                        type: 'MULTIPLE_FOUND',
                    })
                })
                test('Must unlink conflicting app if conflictPolicy is set to "setNull"', async () => {
                    const devApp = environment === DEV_ENVIRONMENT ? fromApp : null
                    const prodApp = devApp ? null : fromApp
                    // Get the originally auto-linked condo app before import
                    const exportField = environment === DEV_ENVIRONMENT ? 'developmentExportId' : 'productionExportId'
                    const appBefore = await B2BApp.getOne(support, { id: app.id })
                    const originalCondoAppId = appBefore[exportField]
                    expect(originalCondoAppId).not.toBeNull()

                    const [result] = await importB2BAppByTestClient(support, app, devApp, prodApp, { options: { conflictPolicy: 'setNull' } })
                    expect(result).toHaveProperty('success', true)

                    // Check that fromApp is now linked to the dev-portal app
                    const updatedFromApp = await CondoB2BApp.getOne(condoAdmin, { id: fromApp.id })
                    expect(updatedFromApp).toHaveProperty('importId', app.id)
                    expect(updatedFromApp).toHaveProperty('importRemoteSystem', REMOTE_SYSTEM)

                    // Check that the originally auto-linked condo app was unlinked (importId set to null)
                    const originalCondoApp = await CondoB2BApp.getOne(condoAdmin, { id: originalCondoAppId })
                    expect(originalCondoApp).toHaveProperty('importId', null)
                    expect(originalCondoApp).toHaveProperty('importRemoteSystem', null)
                })
                test('Must delete previously linked app if conflictPolicy is set to "delete"', async () => {
                    const devApp = environment === DEV_ENVIRONMENT ? fromApp : null
                    const prodApp = devApp ? null : fromApp
                    // Get the originally auto-linked condo app before import
                    const exportField = environment === DEV_ENVIRONMENT ? 'developmentExportId' : 'productionExportId'
                    const appBefore = await B2BApp.getOne(support, { id: app.id })
                    const originalCondoAppId = appBefore[exportField]
                    expect(originalCondoAppId).not.toBeNull()

                    const [result] = await importB2BAppByTestClient(support, app, devApp, prodApp, { options: { conflictPolicy: 'delete' } })
                    expect(result).toHaveProperty('success', true)

                    // Check that fromApp is now linked to the dev-portal app
                    const updatedFromApp = await CondoB2BApp.getOne(condoAdmin, { id: fromApp.id })
                    expect(updatedFromApp).toHaveProperty('importId', app.id)
                    expect(updatedFromApp).toHaveProperty('importRemoteSystem', REMOTE_SYSTEM)
                    expect(updatedFromApp).toHaveProperty('deletedAt', null)

                    // Check that the originally auto-linked condo app was soft-deleted
                    const originalCondoApp = await CondoB2BApp.getOne(condoAdmin, { id: originalCondoAppId })
                    expect(originalCondoApp).not.toBeDefined()
                })
            })
        })
    })
})